function [kp] = ap2kp(ap)
%AP2KP  ap2kp (atmos.spaceweather): the nearest node, ap clamped to [0, 400].
%   ap: real[1] (passed a plain number)
%   returns kp: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    kp = 0;
    if isnan(ap)
        kp = NaN;
    else
        kp = asils.models.swindex.kp_ap_nearest(false, asils.pc.fmax(asils.pc.fmin(ap, 400), 0));
    end
end
